CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_invoice_add_seat`(
    IN p_invoice_id BINARY(16), 
    IN p_showtime_seat_id INT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_price DECIMAL(10,2);
    SELECT st.price INTO v_price 
    FROM showtime_seat ss 
    JOIN seat s ON ss.seat_id = s.seat_id 
    JOIN seat_type st ON s.seat_type_id = st.seat_type_id
    WHERE ss.showtime_seat_id = p_showtime_seat_id;

    INSERT INTO booking_seat(invoice_id, showtime_seat_id, user_id, price_at_booking, showtime_id)
    SELECT p_invoice_id, p_showtime_seat_id, p_user_id, v_price, showtime_id 
    FROM showtime_seat WHERE showtime_seat_id = p_showtime_seat_id;
END ;;
DELIMITER ;
