CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_invoice_calculate_total`(
    IN p_invoice_id BINARY(16) 
)
BEGIN
    DECLARE v_total DECIMAL(12,2);
    
    SELECT SUM(price_at_booking) INTO v_total FROM booking_seat WHERE invoice_id = p_invoice_id;
    
    UPDATE invoice SET total_price = v_total, final_price = v_total WHERE invoice_id = p_invoice_id;
END ;;
