BEGIN
    DECLARE v_new_uuid BINARY(16);
    SET v_new_uuid = UUID_TO_BIN(UUID()); 

    
    INSERT INTO invoice(invoice_id, user_id, created_datetime, invoice_status)
    VALUES(v_new_uuid, p_user_id, NOW(), 'draft');

    
    SELECT BIN_TO_UUID(v_new_uuid) AS invoice_id;
END ;;
