CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_payment_success`(
    IN p_invoice_id BINARY(16) 
)
BEGIN
    START TRANSACTION;
    
    UPDATE showtime_seat ss
    JOIN booking_seat bs ON ss.showtime_seat_id = bs.showtime_seat_id
    SET ss.status_id = 3 WHERE bs.invoice_id = p_invoice_id;

    UPDATE invoice SET invoice_status = 'paid', paid_at = NOW() WHERE invoice_id = p_invoice_id;
    COMMIT;
END ;;
