CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_release_expired_seat`()
BEGIN
    UPDATE showtime_seat
    SET status_id       = 1,
        user_id         = NULL,
        hold_expired_at = NULL
    WHERE status_id     = 2
      AND hold_expired_at < NOW();
END ;;
